<?php $token=(string)($data['token']??'');$valid=!$error && preg_match('/^[a-f0-9]{64}$/D',$token); ?>
<section class="wrap flow-card confirmation-card"><span class="flow-icon" aria-hidden="true"><?= $valid?'↻':'✉' ?></span><h1><?= e($t($valid?'verification.pending':'verification.unavailable')) ?></h1><p role="status"><?= e($t($valid?'verification.pending_desc':'verification.recover')) ?></p>
<?php if($valid): ?><form method="post" action="<?= $url('verify') ?>" data-auto-verification><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="token" value="<?= e($token) ?>"><button class="button"><?= e($t('verification.confirm')) ?> <span aria-hidden="true">↗</span></button></form><?php endif ?>
<a class="text-link recovery" href="<?= $url('resend') ?>"><?= e($t('resend')) ?></a></section>
